function summarizeOrder(quantity, price, coupon) {
  const numericQuantity = Number(quantity);
  const total = numericQuantity * price;
  const normalizedCoupon = coupon ?? '쿠폰 없음';
  const freeShipping = total >= 50000;
  return { quantity: numericQuantity, total, coupon: normalizedCoupon, freeShipping };
}
